// No network, no secrets. Auth is done only by an n8n Credential on the HTTP nodes.
const cfg = $input.first().json;
const base = typeof cfg.backend_base_url === 'string' ? cfg.backend_base_url.trim() : '';
const eventIdRaw = typeof cfg.event_id === 'string' ? cfg.event_id.trim() : '';
const eventId = eventIdRaw.toLowerCase();
const missing = [];
let origin = '';
if (base === '') {
  missing.push('backend_base_url');
} else {
  const m = /^https:\/\/([A-Za-z0-9.-]+)(:[0-9]{1,5})?(\/.*)?$/.exec(base);
  if (!m) missing.push('backend_base_url must be an https:// URL');
  else origin = 'https://' + m[1] + (m[2] || '');
}
if (eventIdRaw === '') missing.push('event_id');
else if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(eventId)) missing.push('event_id must be a UUID');

if (missing.length > 0) {
  return [{ json: { config_ok: false, status: 'error', error_code: 'CONFIG_REQUIRED', message: 'Integration config is incomplete. No HTTP request was made.', missing } }];
}

const requestBody = {
  schema_version: '1.0',
  locale: 'ru',
  consent_version: 'terms_v1',
  privacy_version: 'privacy_v1',
  parent_job_id: null,
  input: {
    kind: 'form',
    capital_tiyin: '10000000000',
    horizon_months: 12,
    selected_risk: 'moderate',
    loss_capacity: 2,
    loss_behavior: 1,
    experience: 2,
    max_loss_bps: 2000,
    crypto_opt_in: false,
    resident_uz: true,
    adult_confirmed: true,
    reserve_confirmed: true,
    risk_acknowledged: true,
  },
};
return [{ json: {
  config_ok: true,
  backend_origin: origin,
  create_url: origin + '/api/v1/portfolio/generate',
  deadline_ms: Date.now() + 45000,
  idempotency_key: eventId,
  event_id: eventId,
  request_body: requestBody,
} }];

const cfg = $('Validate config and request').first().json;
const res = $input.first().json;
const fail = (code, extra) => [{ json: Object.assign({ poll: false, status: 'error', error_code: code, idempotency_key: cfg.idempotency_key, retry_hint: 'Retry POST only with the same Idempotency-Key.' }, extra) }];
if (res.error !== undefined && res.statusCode === undefined) {
  return fail('NETWORK_ERROR', { message: 'POST failed or timed out before a response was received. The job may or may not exist.' });
}
if (Date.now() > cfg.deadline_ms) {
  return fail('DEADLINE_EXCEEDED', { message: 'Shared 45s deadline passed during POST. A late response is not published as success.', http_status: res.statusCode || null });
}
const body = res.body !== null && typeof res.body === 'object' ? res.body : {};
if (res.statusCode !== 202 || typeof body.job_id !== 'string' || !/^[A-Za-z0-9_-]{1,128}$/.test(body.job_id)) {
  return fail('CREATE_FAILED', { http_status: res.statusCode || null, message: 'Backend did not return 202 with a valid job_id.' });
}
return [{ json: {
  poll: true,
  job_id: body.job_id,
  poll_url: cfg.backend_origin + '/api/v1/portfolio/jobs/' + encodeURIComponent(body.job_id),
  idempotency_key: cfg.idempotency_key,
  deadline_ms: cfg.deadline_ms,
} }];

const init = $('Init polling').first().json;
const remaining = init.deadline_ms - Date.now();
const base = { job_id: init.job_id, idempotency_key: init.idempotency_key, remaining_ms: remaining };
if (remaining < 1000) {
  return [{ json: Object.assign({ proceed: false, deadline_expired: true }, base) }];
}
return [{ json: Object.assign({ proceed: true }, base) }];

const init = $('Init polling').first().json;
const res = $input.first().json;
const base = { job_id: init.job_id, idempotency_key: init.idempotency_key, poll_attempts: $runIndex + 1, retry_hint: 'Retry POST only with the same Idempotency-Key.' };
const err = (code, extra) => [{ json: Object.assign({ wait: false, status: 'error', error_code: code }, base, extra) }];
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

if (res.deadline_expired === true) {
  return err('POLL_TIMEOUT', { message: 'Shared 45s deadline reached before the next GET. The request was not sent.' });
}
if (res.error !== undefined && res.statusCode === undefined) {
  return err('NETWORK_ERROR', { message: 'GET failed or timed out. Do not create a new job: reuse the same Idempotency-Key.' });
}
if (Date.now() > init.deadline_ms) {
  return err('POLL_TIMEOUT', { message: 'Shared 45s deadline passed. A late response is not published.' });
}
if (res.statusCode !== 200) {
  return err('POLL_HTTP_ERROR', { http_status: res.statusCode || null });
}
const body = isObj(res.body) ? res.body : null;
if (body === null) {
  return err('BACKEND_RESPONSE_INVALID', { message: 'Response body is not a JSON object.' });
}
if (body.job_id !== init.job_id) {
  return err('BACKEND_RESPONSE_INVALID', { message: 'job_id in response does not match the expected job_id.' });
}
const st = body.status;
if (st === 'queued' || st === 'running') {
  // Need 5s of Wait plus at least 1s left for the next GET.
  if (Date.now() + 6000 > init.deadline_ms) {
    return err('POLL_TIMEOUT', { message: 'Polling deadline (45s) reached.', last_status: st });
  }
  return [{ json: Object.assign({ wait: true, status: 'pending', last_status: st }, base) }];
}
if (st === 'needs_input') {
  if (!isObj(body.clarification)) {
    return err('BACKEND_RESPONSE_INVALID', { message: 'needs_input requires an object clarification.' });
  }
  return [{ json: Object.assign({ wait: false, status: 'clarification', clarification: body.clarification }, base) }];
}
if (st === 'completed' || st === 'completed_with_warnings') {
  if (!isObj(body.result)) {
    return err('BACKEND_RESPONSE_INVALID', { message: st + ' requires a non-null object result.' });
  }
  return [{ json: Object.assign({ wait: false, status: st, result: body.result, warnings: Array.isArray(body.warnings) ? body.warnings : [] }, base) }];
}
if (st === 'failed' || st === 'cancelled' || st === 'expired') {
  return err('JOB_' + st.toUpperCase(), { error: isObj(body.error) ? body.error : null });
}
return err('BACKEND_RESPONSE_INVALID', { message: 'Unknown job status.', raw_status: typeof st === 'string' ? st : null });

const j = $input.first().json;
const out = Object.assign({}, j);
delete out.wait; delete out.poll; delete out.config_ok;
out.draft = true;
out.note = 'Integration draft: real backend URL and n8n credential are required.';
return [{ json: out }];
